@df.func
def grid_value(grid: df.tensor(float), ix:int, iy:int, iz:int):
    ny=int(df.load(grid,1));nz=int(df.load(grid,2))
    return df.load(grid,9+(ix*ny+iy)*nz+iz)

@df.func
def sample_grid_sdf(point:df.float3,grid:df.tensor(float)):
    nx=int(df.load(grid,0));ny=int(df.load(grid,1));nz=int(df.load(grid,2))
    ox=df.load(grid,3);oy=df.load(grid,4);oz=df.load(grid,5)
    dx=df.load(grid,6);dy=df.load(grid,7);dz=df.load(grid,8)
    x=df.clamp((point[0]-ox)/dx,0.,float(nx-1)-0.0001)
    y=df.clamp((point[1]-oy)/dy,0.,float(ny-1)-0.0001)
    z=df.clamp((point[2]-oz)/dz,0.,float(nz-1)-0.0001)
    ix=int(x);iy=int(y);iz=int(z)
    fx=x-float(ix);fy=y-float(iy);fz=z-float(iz)
    a=grid_value(grid,ix,iy,iz)*(1.-fx)+grid_value(grid,ix+1,iy,iz)*fx
    b=grid_value(grid,ix,iy+1,iz)*(1.-fx)+grid_value(grid,ix+1,iy+1,iz)*fx
    c=grid_value(grid,ix,iy,iz+1)*(1.-fx)+grid_value(grid,ix+1,iy,iz+1)*fx
    d=grid_value(grid,ix,iy+1,iz+1)*(1.-fx)+grid_value(grid,ix+1,iy+1,iz+1)*fx
    value=((1.-fy)*a+fy*b)*(1.-fz)+((1.-fy)*c+fy*d)*fz
    outside=point-df.float3(ox+x*dx,oy+y*dy,oz+z*dz)
    return value+df.length(outside)

@df.func
def grid_knife_sdf(point: df.float3, spine_dim: float, spine_height: float, edge_dim: float, tip_height: float, depth: float, radius: float, grid: df.tensor(float)):
    return sample_grid_sdf(point, grid) - radius

@df.func
def grid_knife_sdf_grad(point: df.float3, spine_dim: float, spine_height: float, edge_dim: float, tip_height: float, depth: float, radius: float, grid: df.tensor(float)):
    eps = 1e-05
    dx0 = grid_knife_sdf(df.float3(point[0] - eps, point[1], point[2]), spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    dx1 = grid_knife_sdf(df.float3(point[0] + eps, point[1], point[2]), spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    dy0 = grid_knife_sdf(df.float3(point[0], point[1] - eps, point[2]), spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    dy1 = grid_knife_sdf(df.float3(point[0], point[1] + eps, point[2]), spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    dz0 = grid_knife_sdf(df.float3(point[0], point[1], point[2] - eps), spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    dz1 = grid_knife_sdf(df.float3(point[0], point[1], point[2] + eps), spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    eps2 = 2.0 * eps
    return df.float3((dx1 - dx0) / eps2, (dy1 - dy0) / eps2, (dz1 - dz0) / eps2)

@df.func
def grid_edge_knife_sdf(u: float, a: df.float3, b: df.float3, spine_dim: float, spine_height: float, edge_dim: float, tip_height: float, depth: float, radius: float, grid: df.tensor(float)):
    p = a * u + b * (1.0 - u)
    return grid_knife_sdf(p, spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)

@df.func
def grid_edge_knife_sdf_grad(u: float, a: df.float3, b: df.float3, spine_dim: float, spine_height: float, edge_dim: float, tip_height: float, depth: float, radius: float, grid: df.tensor(float)):
    eps = 1e-05
    du0 = grid_edge_knife_sdf(u - eps, a, b, spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    du1 = grid_edge_knife_sdf(u + eps, a, b, spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    return (du1 - du0) / (2.0 * eps)

@df.func
def grid_edge_knife_sdf_collision(t: float, xi_shape: df.float3, xj_shape: df.float3, spine_dim: float, spine_height: float, edge_dim: float, tip_height: float, depth: float, radius: float, cut_edge_index: int, cut_edge_contact_dist: df.tensor(float), cut_edge_contact_coord: df.tensor(float), cut_edge_contact_normal: df.tensor(df.float3), grid: df.tensor(float)):
    u = 0.5 * t
    k = 1.0
    for iteration in range(0, 20):
        grad = grid_edge_knife_sdf_grad(u, xj_shape, xi_shape, spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
        s = df.max(df.sign(0.0 - grad), 0.0) * t
        gamma = 2.0 / (2.0 + k)
        u = u + gamma * (s - u)
        k = k + 1.0
    p_shape = xi_shape * (1.0 - u) + xj_shape * u
    c_dist = grid_knife_sdf(p_shape, spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid)
    n = df.normalize(grid_knife_sdf_grad(p_shape, spine_dim, spine_height, edge_dim, tip_height, depth, radius, grid))
    df.store(cut_edge_contact_dist, cut_edge_index, c_dist)
    df.store(cut_edge_contact_coord, cut_edge_index, u)
    df.store(cut_edge_contact_normal, cut_edge_index, n)
    return c_dist

